def eventualSafeNodes(V, adj):
    def dfs(node, visited, rec_stack, safe):
        visited[node] = True
        rec_stack[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if not dfs(neighbor, visited, rec_stack, safe):
                    return False
            elif rec_stack[neighbor]:
                return False

        rec_stack[node] = False
        safe.append(node)
        return True

    visited = [False] * V
    rec_stack = [False] * V
    safe = []

    for node in range(V):
        if not visited[node]:
            dfs(node, visited, rec_stack, safe)

    safe.sort()
    return safe

# Example usage:
# V = 7
# adj = [[1, 2], [2, 3], [5], [0], [5], [], []]
# print(eventualSafeNodes(V, adj))  # Output: [2, 4, 5, 6]
